<?php get_header(); ?><article class="or-article"><div class="or-container"><header class="or-article-header"><?php or_breadcrumbs(); ?><p class="or-eyebrow">Review de produto</p><h1><?php the_title(); ?></h1><p class="or-article-lead"><?php echo esc_html(get_the_excerpt()); ?></p><?php if(has_post_thumbnail()): ?><div class="or-featured"><?php the_post_thumbnail('full',array('loading'=>'eager')); ?></div><?php endif; ?></header><div class="or-content"><section class="or-summary"><p class="or-eyebrow">Resumo</p><?php the_content(); ?></section><?php $fields=array('or_characteristics'=>'Características','or_pros'=>'Pontos positivos','or_cons'=>'Pontos negativos','or_alternatives'=>'Alternativas','or_for_whom'=>'Para quem é indicado'); foreach($fields as $key=>$label): $value=or_meta($key); if($value): ?><section><h2><?php echo esc_html($label); ?></h2><div><?php echo wp_kses_post(wpautop($value)); ?></div></section><?php endif; endforeach; $affiliate=or_meta('or_affiliate_url'); if($affiliate): ?><p class="or-cta-affiliate"><a class="or-btn or-btn-primary" href="<?php echo or_affiliate_url($affiliate); ?>" rel="sponsored noopener noreferrer" target="_blank">Ver preço atualizado</a></p><?php endif; ?></div></div></article><?php get_footer(); ?>
